"use client";

import { motion, useReducedMotion } from "motion/react";
import type { ComponentProps } from "react";

export type HoldToConfirmPrimitiveProps = ComponentProps<typeof motion.div>;

export function HoldToConfirmPrimitive({ children, ...props }: HoldToConfirmPrimitiveProps) {
  const reduceMotion = useReducedMotion();

  return (
    <motion.div
      {...props}
      whileTap={reduceMotion ? undefined : {scale: 0.97}}
      transition={reduceMotion ? { duration: 0.12 } : { duration: 1.2, ease: "linear" }}
    >
      {children}
    </motion.div>
  );
}
